import { notFound } from "@/lib/http/errors";
import { defineRoute } from "@/lib/http/handler";
import { MediaParams, readMedia } from "@/modules/listings";

/**
 * GET /api/v1/media/:orgId/:file — serves re-encoded listing images. Keys are random UUIDs
 * generated by the server; only `<uuid>.webp` names are accepted (no path traversal).
 */
export const GET = defineRoute({ public: true, params: MediaParams }, async ({ params }) => {
  const body = await readMedia(`org/${params.orgId}/${params.file}`);
  if (!body) throw notFound("Image");
  return new Response(new Uint8Array(body), {
    status: 200,
    headers: {
      "Content-Type": "image/webp",
      "Content-Length": String(body.byteLength),
      "Cache-Control": "public, max-age=31536000, immutable",
      "X-Content-Type-Options": "nosniff",
      "Content-Disposition": "inline",
    },
  });
});
